syntax:
Type variable_name = (Type){ .member1 = value1, .member2 = value2, ... }; // for structures
Type array_name[] = { [index] = value, ... }; // for arrays
// or using designated initializers for nested structures and arrays
Type complex_var = (Type){ .array_member = { [index] = value, ... }, .struct_member = { .submember = value } };
